import fs from "node:fs"
import path from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"
import openapiTS, { astToString } from "openapi-typescript"

const webDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const documentPath = path.resolve(webDir, "../api/openapi.yaml")
const outFile = path.join(webDir, "src/api/schema.gen.ts")
const banner =
  "/* Generated by web/scripts/gen-api.mjs from api/openapi.yaml. Do not edit; run make generate. */"

const ast = await openapiTS(pathToFileURL(documentPath))
const content = `${banner}\n${astToString(ast)}`

if (process.argv.includes("--check")) {
  if (!fs.existsSync(outFile) || fs.readFileSync(outFile, "utf8") !== content) {
    console.error(
      "web/src/api/schema.gen.ts is stale; run make generate and commit the result"
    )
    process.exit(1)
  }
} else {
  fs.mkdirSync(path.dirname(outFile), { recursive: true })
  fs.writeFileSync(outFile, content)
}
